package com.franco.desco.adapter.out.sqlserver.sanitation;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.sanitation.*;import com.franco.desco.application.sanitation.port.out.SanitationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.sanitation.SanitationModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class SanitationSqlServerAdapter implements SanitationPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,create,update,state,close,treatment,follow;public SanitationSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("sanidad","PA_CasoFitosanitario_Sel_Listado","items");get=f.callWithResultSets("sanidad","PA_CasoFitosanitario_Sel_DetalleCompleto","header","treatments","followups","files");create=f.call("sanidad","PA_CasoFitosanitario_Ins_Registro");update=f.call("sanidad","PA_CasoFitosanitario_Upd_Registro");state=f.call("sanidad","PA_CasoFitosanitario_Upd_Estado");close=f.call("sanidad","PA_CasoFitosanitario_Upd_Cerrar");treatment=f.call("sanidad","PA_TratamientoFitosanitario_Ins_Registro");follow=f.call("sanidad","PA_SeguimientoFitosanitario_Ins_Registro");}
 public PersistenceResult<PageResult<SanitationModels.Summary>>list(SanitationCommands.ListCases c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var payload=pf.forQuery(i,m,map("filtros",map("estadoCaso",f==null?null:f.estadoCaso(),"severidad",f==null?null:f.severidad(),"predioId",f==null?null:f.predioId(),"socioId",f==null?null:f.socioId(),"tipoProblemaId",f==null?null:f.tipoProblemaId(),"fechaDesde",f==null?null:f.fechaDesde(),"fechaHasta",f==null?null:f.fechaHasta()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio())));var out=e.executeJson(list,payload);return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar los casos fitosanitarios.");}
 public PersistenceResult<SanitationModels.Detail>get(SanitationCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("caso",Map.of("casoFitosanitarioId",c.casoFitosanitarioId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar el caso."));var h=one(out,"header");if(h==null)return PersistenceResult.error("El caso seleccionado no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Caso consultado correctamente."),new SanitationModels.Detail(header(h),rows(out,"treatments").stream().map(this::treatment).toList(),rows(out,"followups").stream().map(this::follow).toList(),rows(out,"files").stream().map(this::file).toList()));}
 public PersistenceResult<Long>create(SanitationCommands.Create c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(create,pf.forWrite(i,m,c,Map.of("caso",map("parcelaCultivoId",c.parcelaCultivoId(),"tipoProblemaId",c.tipoProblemaId(),"visitaDeteccionId",c.visitaDeteccionId(),"fechaDeteccion",c.fechaDeteccion(),"plantasAfectadas",c.plantasAfectadas(),"cantidadEstimada",c.cantidadEstimada(),"severidad",c.severidad(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nCasoFitosanitarioId"),"No se pudo registrar el caso.");}
 public PersistenceResult<Void>update(SanitationCommands.Update c,SessionIdentity i,RequestMetadata m){return mut(update,i,m,c,"caso",map("casoFitosanitarioId",c.casoFitosanitarioId(),"tipoProblemaId",c.tipoProblemaId(),"plantasAfectadas",c.plantasAfectadas(),"cantidadEstimada",c.cantidadEstimada(),"severidad",c.severidad(),"observacion",c.observacion()),"No se pudo actualizar el caso.");}public PersistenceResult<Void>changeState(SanitationCommands.ChangeState c,SessionIdentity i,RequestMetadata m){return mut(state,i,m,c,"caso",map("casoFitosanitarioId",c.casoFitosanitarioId(),"nuevoEstado",c.nuevoEstado(),"motivo",c.motivo()),"No se pudo actualizar el estado del caso.");}public PersistenceResult<Void>close(SanitationCommands.Close c,SessionIdentity i,RequestMetadata m){return mut(close,i,m,c,"caso",map("casoFitosanitarioId",c.casoFitosanitarioId(),"motivo",c.motivo()),"No se pudo cerrar el caso.");}
 public PersistenceResult<Long>addTreatment(SanitationCommands.Treatment c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(treatment,pf.forWrite(i,m,c,Map.of("tratamiento",map("casoFitosanitarioId",c.casoFitosanitarioId(),"visitaTecnicaId",c.visitaTecnicaId(),"responsableEmpleadoId",c.responsableEmpleadoId(),"fechaHora",c.fechaHora(),"tratamiento",c.tratamiento(),"producto",c.producto(),"dosis",c.dosis(),"unidadDosis",c.unidadDosis(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nTratamientoId"),"No se pudo registrar el tratamiento.");}
 public PersistenceResult<Long>addFollowUp(SanitationCommands.FollowUp c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(follow,pf.forWrite(i,m,c,Map.of("seguimiento",map("casoFitosanitarioId",c.casoFitosanitarioId(),"visitaTecnicaId",c.visitaTecnicaId(),"fechaHora",c.fechaHora(),"plantasAfectadas",c.plantasAfectadas(),"cantidadEstimada",c.cantidadEstimada(),"severidad",c.severidad(),"resultado",c.resultado(),"observacion",c.observacion()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nSeguimientoId"),"No se pudo registrar el seguimiento.");}
 private PersistenceResult<Void>mut(SimpleJdbcCall call,SessionIdentity i,RequestMetadata m,Object body,String root,Map<String,Object>v,String f){return PaAdapterSupport.result(e.executeJson(call,pf.forWrite(i,m,body,Map.of(root,v))),null,f);}private SanitationModels.Summary summary(Map<String,Object>r){return new SanitationModels.Summary(SqlValues.longValue(r,"casoFitosanitarioId"),SqlValues.instant(r,"fechaDeteccion"),SqlValues.string(r,"estadoCaso"),SqlValues.string(r,"severidad"),SqlValues.intValue(r,"plantasAfectadas"),SqlValues.bool(r,"cantidadEstimada"),SqlValues.string(r,"codigoProblema"),SqlValues.string(r,"problema"),SqlValues.longValue(r,"parcelaCultivoId"),SqlValues.longValue(r,"parcelaId"),SqlValues.string(r,"parcelaNombre"),SqlValues.longValue(r,"predioId"),SqlValues.string(r,"predioCodigo"),SqlValues.string(r,"predioNombre"),SqlValues.longValue(r,"socioId"),SqlValues.string(r,"numeroDocumento"),SqlValues.string(r,"socioNombre"),SqlValues.longValue(r,"evidencias"));}private SanitationModels.Header header(Map<String,Object>r){return new SanitationModels.Header(SqlValues.longValue(r,"casoFitosanitarioId"),SqlValues.longValue(r,"parcelaCultivoId"),SqlValues.intValue(r,"tipoProblemaId"),SqlValues.string(r,"codigoProblema"),SqlValues.string(r,"categoria"),SqlValues.string(r,"problema"),SqlValues.longValue(r,"visitaDeteccionId"),SqlValues.instant(r,"fechaDeteccion"),SqlValues.intValue(r,"plantasAfectadas"),SqlValues.bool(r,"cantidadEstimada"),SqlValues.string(r,"severidad"),SqlValues.string(r,"estadoCaso"),SqlValues.string(r,"observacion"),SqlValues.longValue(r,"parcelaId"),SqlValues.string(r,"parcelaNombre"),SqlValues.longValue(r,"predioId"),SqlValues.string(r,"predioCodigo"),SqlValues.string(r,"predioNombre"),SqlValues.string(r,"variedad"));}private SanitationModels.Treatment treatment(Map<String,Object>r){return new SanitationModels.Treatment(SqlValues.longValue(r,"tratamientoId"),SqlValues.instant(r,"fechaHora"),SqlValues.longValue(r,"visitaTecnicaId"),SqlValues.longValue(r,"responsableEmpleadoId"),SqlValues.string(r,"responsable"),SqlValues.string(r,"tratamiento"),SqlValues.string(r,"producto"),SqlValues.decimal(r,"dosis"),SqlValues.string(r,"unidadDosis"),SqlValues.string(r,"observacion"));}private SanitationModels.FollowUp follow(Map<String,Object>r){return new SanitationModels.FollowUp(SqlValues.longValue(r,"seguimientoId"),SqlValues.instant(r,"fechaHora"),SqlValues.longValue(r,"visitaTecnicaId"),SqlValues.intValue(r,"plantasAfectadas"),SqlValues.bool(r,"cantidadEstimada"),SqlValues.string(r,"severidad"),SqlValues.string(r,"resultado"),SqlValues.string(r,"observacion"));}private SanitationModels.File file(Map<String,Object>r){return new SanitationModels.File(SqlValues.longValue(r,"archivoId"),SqlValues.string(r,"nombreOriginal"),SqlValues.string(r,"mimeType"),SqlValues.string(r,"secureUrl"),SqlValues.string(r,"categoria"),SqlValues.string(r,"origenCaptura"),SqlValues.string(r,"descripcion"),SqlValues.instant(r,"fechaCarga"),SqlValues.instant(r,"fechaCaptura"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
